   356→// parseIfStatement parses an if statement
   357→func (p *Parser) parseIfStatement() (ast.Statement, error) {
   358→	cond, err := p.parseExpression()
   359→	if err != nil {
   360→		return nil, err
   361→	}
   362→
   363→	if !p.match(lexer.TknLBrace) {
   364→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   365→	}
   366→
   367→	var thenBody []ast.Statement
   368→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   369→		stmt, err := p.parseStatement()
   370→		if err != nil {
   371→			return nil, err
   372→		}
   373→		if stmt != nil {
   374→			thenBody = append(thenBody, stmt)
   375→		}
   376→	}
   377→
   378→	if !p.match(lexer.TknRBrace) {
   379→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   380→	}
   381→
   382→	var elseBody []ast.Statement
   383→	if p.match(lexer.TknElse) {
   384→		if p.match(lexer.TknLBrace) {
   385→			for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   386→				stmt, err := p.parseStatement()
   387→				if err != nil {
   388→					return nil, err
   389→				}
   390→				if stmt != nil {
   391→					elseBody = append(elseBody, stmt)
   392→				}
   393→			}
   394→
   395→			if !p.match(lexer.TknRBrace) {
   396→				return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   397→			}
   398→		}
   399→	}
   400→
   401→	return &ast.IfStatement{
   402→		Condition: cond,
   403→		ThenBody:  thenBody,
   404→		ElseBody:  elseBody,
   405→	}, nil
   406→}
