   408→// parseForStatement parses a for loop
   409→func (p *Parser) parseForStatement() (ast.Statement, error) {
   410→	varName := p.current().Text
   411→	if !p.match(lexer.TknIdentifier) {
   412→		return nil, fmt.Errorf("expected variable name at %d:%d", p.current().Line, p.current().Column)
   413→	}
   414→
   415→	if !p.match(lexer.TknIn) {
   416→		return nil, fmt.Errorf("expected 'in' at %d:%d", p.current().Line, p.current().Column)
   417→	}
   418→
   419→	iter, err := p.parseExpression()
   420→	if err != nil {
   421→		return nil, err
   422→	}
   423→
   424→	if !p.match(lexer.TknLBrace) {
   425→		return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   426→	}
   427→
   428→	var body []ast.Statement
   429→	for !p.check(lexer.TknRBrace) && !p.isAtEnd() {
   430→		stmt, err := p.parseStatement()
   431→		if err != nil {
   432→			return nil, err
   433→		}
   434→		if stmt != nil {
   435→			body = append(body, stmt)
   436→		}
   437→	}
   438→
   439→	if !p.match(lexer.TknRBrace) {
   440→		return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   441→	}
   442→
   443→	// Check if iter is a range (BinaryExpression with .. operator)
   444→	if binExpr, ok := iter.(*ast.BinaryExpression); ok && binExpr.Operator == ".." {
   445→		return &ast.ForRangeStatement{
   446→			Variable: varName,
   447→			Start:    binExpr.Left,
   448→			End:      binExpr.Right,
   449→			Body:     body,
   450→		}, nil
   451→	}
   452→
   453→	return &ast.ForStatement{
   454→		Variable: varName,
   455→		Iterator: iter,
   456→		Body:     body,
   457→	}, nil
   458→}
