   605→// parseUnary parses unary expressions
   606→func (p *Parser) parseUnary() (ast.Expression, error) {
   607→	if p.match(lexer.TknNot) {
   608→		operand, err := p.parseUnary()
   609→		if err != nil {
   610→			return nil, err
   611→		}
   612→		return &ast.UnaryExpression{
   613→			Operator: "!",
   614→			Operand:  operand,
   615→		}, nil
   616→	}
   617→
   618→	if p.match(lexer.TknMinus) {
   619→		operand, err := p.parseUnary()
   620→		if err != nil {
   621→			return nil, err
   622→		}
   623→		return &ast.UnaryExpression{
   624→			Operator: "-",
   625→			Operand:  operand,
   626→		}, nil
   627→	}
   628→
   629→	if p.match(lexer.TknAmpersand) {
   630→		operand, err := p.parseUnary()
   631→		if err != nil {
   632→			return nil, err
   633→		}
   634→		return &ast.UnaryExpression{
   635→			Operator: "&",
   636→			Operand:  operand,
   637→		}, nil
   638→	}
   639→
   640→	return p.parsePostfix()
   641→}
