   742→// parsePrimary parses primary expressions
   743→func (p *Parser) parsePrimary() (ast.Expression, error) {
   744→	// Literals
   745→	if p.match(lexer.TknInteger) {
   746→		val, err := strconv.ParseInt(p.previous().Text, 10, 64)
   747→		if err != nil {
   748→			return nil, fmt.Errorf("invalid integer: %s", p.previous().Text)
   749→		}
   750→		return &ast.IntegerLiteral{Value: val}, nil
   751→	}
   752→
   753→	if p.match(lexer.TknFloat) {
   754→		val, err := strconv.ParseFloat(p.previous().Text, 64)
   755→		if err != nil {
   756→			return nil, fmt.Errorf("invalid float: %s", p.previous().Text)
   757→		}
   758→		return &ast.FloatLiteral{Value: val}, nil
   759→	}
   760→
   761→	if p.match(lexer.TknString) {
   762→		return &ast.StringLiteral{Value: p.previous().Text}, nil
   763→	}
   764→
   765→	if p.match(lexer.TknTrue) {
   766→		return &ast.BoolLiteral{Value: true}, nil
   767→	}
   768→
   769→	if p.match(lexer.TknFalse) {
   770→		return &ast.BoolLiteral{Value: false}, nil
   771→	}
   772→
   773→	if p.match(lexer.TknNone) {
   774→		return &ast.NoneLiteral{}, nil
   775→	}
   776→
   777→	if p.match(lexer.TknIdentifier) {
   778→		return &ast.Identifier{Name: p.previous().Text}, nil
   779→	}
   780→
   781→	if p.match(lexer.TknLBracket) {
   782→		// Array literal
   783→		var elements []ast.Expression
   784→		if !p.check(lexer.TknRBracket) {
   785→			for {
   786→				elem, err := p.parseExpression()
   787→				if err != nil {
   788→					return nil, err
   789→				}
   790→				elements = append(elements, elem)
   791→
   792→				if !p.match(lexer.TknComma) {
   793→					break
   794→				}
   795→			}
   796→		}
   797→
   798→		if !p.match(lexer.TknRBracket) {
   799→			return nil, fmt.Errorf("expected ']' at %d:%d", p.current().Line, p.current().Column)
   800→		}
   801→
   802→		return &ast.ArrayExpression{Elements: elements}, nil
   803→	}
   804→
   805→	if p.match(lexer.TknIf) {
   806→		// Parse if expression
   807→		cond, err := p.parseExpression()
   808→		if err != nil {
   809→			return nil, err
   810→		}
   811→
   812→		if !p.match(lexer.TknLBrace) {
   813→			return nil, fmt.Errorf("expected '{' at %d:%d", p.current().Line, p.current().Column)
   814→		}
   815→
   816→		thenExpr, err := p.parseExpression()
   817→		if err != nil {
   818→			return nil, err
   819→		}
   820→
   821→		if !p.match(lexer.TknRBrace) {
   822→			return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   823→		}
   824→
   825→		var elseExpr ast.Expression
   826→		if p.match(lexer.TknElse) {
   827→			if p.match(lexer.TknLBrace) {
   828→				var err error
   829→				elseExpr, err = p.parseExpression()
   830→				if err != nil {
   831→					return nil, err
   832→				}
   833→
   834→				if !p.match(lexer.TknRBrace) {
   835→					return nil, fmt.Errorf("expected '}' at %d:%d", p.current().Line, p.current().Column)
   836→				}
   837→			}
   838→		}
   839→
   840→		return &ast.IfExpression{
   841→			Condition: cond,
   842→			ThenExpr:  thenExpr,
   843→			ElseExpr:  elseExpr,
   844→		}, nil
   845→	}
   846→
   847→	if p.match(lexer.TknLParen) {
   848→		expr, err := p.parseExpression()
   849→		if err != nil {
   850→			return nil, err
   851→		}
   852→
   853→		if !p.match(lexer.TknRParen) {
   854→			return nil, fmt.Errorf("expected ')' at %d:%d", p.current().Line, p.current().Column)
   855→		}
   856→
   857→		return expr, nil
   858→	}
   859→
   860→	return nil, fmt.Errorf("unexpected token: %v at %d:%d", p.current().Type, p.current().Line, p.current().Column)
   861→}
