   863→// parsePattern parses a pattern
   864→func (p *Parser) parsePattern() (ast.Pattern, error) {
   865→	if p.match(lexer.TknIdentifier) {
   866→		return &ast.IdentifierPattern{Name: p.previous().Text}, nil
   867→	}
   868→
   869→	if p.match(lexer.TknInteger) {
   870→		val, _ := strconv.ParseInt(p.previous().Text, 10, 64)
   871→		return &ast.LiteralPattern{Value: &ast.IntegerLiteral{Value: val}}, nil
   872→	}
   873→
   874→	if p.match(lexer.TknString) {
   875→		return &ast.LiteralPattern{Value: &ast.StringLiteral{Value: p.previous().Text}}, nil
   876→	}
   877→
   878→	if p.match(lexer.TknTilde) {
   879→		return &ast.WildcardPattern{}, nil
   880→	}
   881→
   882→	return nil, fmt.Errorf("unexpected pattern at %d:%d", p.current().Line, p.current().Column)
   883→}
