   917→// Helper methods
   918→
   919→func (p *Parser) current() lexer.Token {
   920→	if p.pos < len(p.tokens) {
   921→		return p.tokens[p.pos]
   922→	}
   923→	return lexer.Token{Type: lexer.TknEof}
   924→}
   925→
   926→func (p *Parser) previous() lexer.Token {
   927→	if p.pos > 0 {
   928→		return p.tokens[p.pos-1]
   929→	}
   930→	return lexer.Token{Type: lexer.TknEof}
   931→}
   932→
   933→func (p *Parser) advance() lexer.Token {
   934→	curr := p.current()
   935→	if !p.isAtEnd() {
   936→		p.pos++
   937→	}
   938→	return curr
   939→}
   940→
   941→func (p *Parser) match(types ...lexer.TokenType) bool {
   942→	for _, t := range types {
   943→		if p.check(t) {
   944→			p.advance()
   945→			return true
   946→		}
   947→	}
   948→	return false
   949→}
   950→
   951→func (p *Parser) check(t lexer.TokenType) bool {
   952→	if p.isAtEnd() {
   953→		return false
   954→	}
   955→	return p.current().Type == t
   956→}
   957→
   958→func (p *Parser) isAtEnd() bool {
   959→	return p.current().Type == lexer.TknEof
   960→}
   961→
   962→func (p *Parser) isOperator(t lexer.TokenType) bool {
   963→	// Check if token is an operator
   964→	switch t {
   965→	case lexer.TknPlus, lexer.TknMinus, lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
   966→		return true
   967→	case lexer.TknAmpersand, lexer.TknPipe, lexer.TknCaret, lexer.TknTilde:
   968→		return true
   969→	case lexer.TknLeftShift, lexer.TknRightShift:
   970→		return true
   971→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
   972→		return true
   973→	case lexer.TknLogicalAnd, lexer.TknLogicalOr, lexer.TknNot:
   974→		return true
   975→	case lexer.TknDoubleDot:
   976→		return true
   977→	default:
   978→		return false
   979→	}
   980→}
