   982→func getPrecedence(t lexer.TokenType) int {
   983→	switch t {
   984→	case lexer.TknLogicalOr:
   985→		return 1
   986→	case lexer.TknLogicalAnd:
   987→		return 2
   988→	case lexer.TknEq, lexer.TknNe, lexer.TknLt, lexer.TknLe, lexer.TknGt, lexer.TknGe:
   989→		return 3
   990→	case lexer.TknPlus, lexer.TknMinus:
   991→		return 4
   992→	case lexer.TknStar, lexer.TknSlash, lexer.TknPercent:
   993→		return 5
   994→	case lexer.TknCaret:
   995→		return 6
   996→	case lexer.TknDoubleDot:
   997→		return 3 // Same as comparison for range expressions
   998→	default:
   999→		return 0
  1000→	}
  1001→}
