  1015→func isPrimitiveType(name string) bool {
  1016→	switch name {
  1017→	case "i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "string", "char", "int", "float":
  1018→		return true
  1019→	}
  1020→	return false
  1021→}
