  1023→// synchronize skips tokens until we find a recovery point
  1024→// Used for error recovery to continue parsing after an error
  1025→func (p *Parser) synchronize() {
  1026→	p.advance()
  1027→
  1028→	for !p.isAtEnd() {
  1029→		// Stop at definition keywords
  1030→		if p.check(lexer.TknFn) || p.check(lexer.TknType) || p.check(lexer.TknStruct) ||
  1031→			p.check(lexer.TknInterface) || p.check(lexer.TknEnum) {
  1032→			return
  1033→		}
  1034→
  1035→		// Stop at statement keywords
  1036→		if p.check(lexer.TknLet) || p.check(lexer.TknConst) || p.check(lexer.TknIf) ||
  1037→			p.check(lexer.TknFor) || p.check(lexer.TknReturn) || p.check(lexer.TknMatch) {
  1038→			return
  1039→		}
  1040→
  1041→		// Stop at block boundaries
  1042→		if p.check(lexer.TknRBrace) {
  1043→			p.advance()
  1044→			return
  1045→		}
  1046→
  1047→		p.advance()
  1048→	}
  1049→}
